                      [disabled]="busy() === c.id"
                      (click)="restore(c)"
                    >
                      Restore
                    </button>
                  } @else {
                    <button
                      type="button"
                      [attr.data-testid]="'client-archive-' + c.id"
                      [attr.aria-label]="'Archive ' + c.name"
                      [disabled]="busy() === c.id"
                      (click)="archive(c)"
                    >
                      Archive
                    </button>
                  }
